EDIT: From my previous reply 2 weeks ago
You might wanna do some more modifications, but this is a start (ATB bar position change not included)
Window_BattleStatus.prototype.maxCols = function() {
return 1;
};
Window_BattleStatus.prototype.itemHeight = function() {
return this.innerHeight / 4;
};
Window_BattleStatus.prototype.drawItem = function(index) {
//    this.drawItemImage(index);
this.drawItemStatus(index);
};
Window_BattleStatus.prototype.nameY = function(rect) {
return rect.y;
};
Window_BattleStatus.prototype.basicGaugesY = function(rect) {
return rect.y;
};
Window_BattleStatus.prototype.placeBasicGauges = function(actor, x, y) {
this.placeGauge(actor, "hp", x + 128, y);
this.placeGauge(actor, "mp", x + 128 * 2, y);
if ($dataSystem.optDisplayTp) {
this.placeGauge(actor, "tp", x + 128 * 3, y);
}
};
